record Msg(String role, String content) {}

interface Llm  { String next(java.util.List<Msg> history); }
interface Tool { String name(); String run(String arg); }

final class AgentLoop {
    private final Llm llm;
    private final java.util.Map<String, Tool> tools = new java.util.HashMap<>();
    private final int maxSteps;

    AgentLoop(Llm llm, int maxSteps) { this.llm = llm; this.maxSteps = maxSteps; }

    void register(Tool t) { tools.put(t.name(), t); }

    String run(String userInput) {
        var history = new java.util.ArrayList<Msg>();
        history.add(new Msg("user", userInput));

        for (int step = 1; step <= maxSteps; step++) {
            String out = llm.next(history);              // ② 决策
            history.add(new Msg("assistant", out));

            if (out.startsWith("FINAL:")) {              // ④ 终止：代码判定
                return out.substring(6).trim();
            }

            String[] parts = out.split(" ", 3);           // CALL <tool> <arg>
            if (parts.length < 2 || !parts[0].equals("CALL")) {
                history.add(new Msg("tool", "ERROR: 动作格式无法解析，请用 CALL <tool> <arg> 或 FINAL: <答案>"));
                continue;
            }
            Tool t = tools.get(parts[1]);
            String arg = parts.length > 2 ? parts[2] : "";
            String result;
            if (t == null) {
                result = "ERROR: 未知工具 " + parts[1] + "，可用：" + tools.keySet();
            } else {
                try { result = t.run(arg); }            // ③ 行动
                catch (Exception e) { result = "ERROR: " + e.getMessage() + "（可重试）"; }
            }
            history.add(new Msg("tool", truncate(result, 2000)));  // ③ 观察回灌
        }
        return "GAVE_UP: 达到最大步数 " + maxSteps;      // ④ 明确放弃，不假装完成
    }

    private static String truncate(String s, int n) {
        return s.length() <= n ? s : s.substring(0, n)
             + "\n[已截断：原文 " + s.length() + " 字符，此处仅前 " + n + "]";
    }
}
